'use strict';
const $=id=>document.getElementById(id), canvas=$('stage'), ctx=canvas.getContext('2d');
const W=1200,H=650;let tool='select',ink='#30392f',paper='#fffef9',brush=4,strokes=[],redo=[],figures=[],selected=null,serial=0,gesture=null,recording=false,playing=false,exporting=false,frames=[],elapsed=0,duration=0,startTime=0,loop=false,take=0,toastTimer;
const clone=x=>JSON.parse(JSON.stringify(x));
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200)}
function figure(x,y){return{id:++serial,name:'Character '+serial,x,y,color:ink,limbs:[[-47,22],[47,22],[-32,116],[32,116]]}}
function addFigure(){if(recording||playing||exporting)return toast('Stop playback or recording before adding characters.');if(figures.length>=8)return toast('Your stage has room for eight characters.');const f=figure(650+(figures.length%3)*100,310);figures.push(f);selected=f.id;setTool('select');renderCast();render()}
function renderCast(){$('cast').replaceChildren();figures.forEach(f=>{const row=document.createElement('div');row.className='cast-row'+(selected===f.id?' selected':'');const select=document.createElement('button');select.className='cast-select';select.textContent='♧  '+f.name;select.onclick=()=>{selected=f.id;setTool('select');renderCast();render()};const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Remove '+f.name);remove.onclick=()=>{if(recording||playing||exporting)return toast('Stop the take before removing a character.');figures=figures.filter(a=>a.id!==f.id);selected=figures[0]?.id;renderCast();render()};row.append(select,remove);$('cast').append(row)})}
function path(points,color,width,erase=false){ctx.save();ctx.strokeStyle=erase?paper:color;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));if(points.length===1)ctx.lineTo(points[0].x+.1,points[0].y);ctx.stroke();ctx.restore()}
function drawFigure(f,handles){ctx.save();ctx.translate(f.x,f.y);ctx.strokeStyle=f.color;ctx.lineWidth=5;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.arc(0,-42,26,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(0,-16);ctx.lineTo(0,60);ctx.stroke();f.limbs.forEach((p,i)=>{ctx.beginPath();ctx.moveTo(0,i<2?7:60);const elbow=[p[0]*.58,p[1]*.5+(i<2?-2:34)];ctx.lineTo(...elbow);ctx.lineTo(...p);ctx.stroke()});ctx.fillStyle=f.color;ctx.beginPath();ctx.arc(-8,-46,2,0,7);ctx.arc(8,-46,2,0,7);ctx.fill();ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-40,10,.2,Math.PI-.2);ctx.stroke();if(handles){ctx.setLineDash([4,6]);ctx.strokeStyle='#b3c796';ctx.lineWidth=1.5;ctx.strokeRect(-70,-84,140,218);ctx.setLineDash([]);f.limbs.forEach(p=>{ctx.beginPath();ctx.arc(...p,6,0,7);ctx.fillStyle=paper;ctx.fill();ctx.strokeStyle='#9ab379';ctx.stroke()})}ctx.restore()}
function render(clean=false){ctx.fillStyle=paper;ctx.fillRect(0,0,W,H);if(!clean){ctx.fillStyle='#dfe4d5';for(let x=24;x<W;x+=24)for(let y=24;y<H;y+=24){ctx.beginPath();ctx.arc(x,y,.7,0,7);ctx.fill()}}strokes.forEach(s=>path(s.points,s.color,s.width,s.erase));if(gesture?.stroke)path(gesture.stroke.points,gesture.stroke.color,gesture.stroke.width,gesture.stroke.erase);figures.forEach(f=>drawFigure(f,!clean&&!playing&&!exporting&&f.id===selected&&tool==='select'));$('emptyHint').hidden=strokes.length>0||frames.length>0||recording||playing||exporting;}
function setTool(t){if(exporting)return;tool=t;document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));canvas.style.cursor=t==='select'?'grab':'crosshair';$('toolHint').textContent={select:'Grab your character and give it a little life.',pen:'Let your imagination wander. Draw directly on the stage.',line:'Drag from one point to another to draw a straight line.',eraser:'Brush over the background to erase a little bit.'}[t];render()}
function point(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height}}
canvas.addEventListener('pointerdown',e=>{if(playing||exporting)return;const p=point(e);canvas.setPointerCapture(e.pointerId);if(tool==='select'){for(const f of [...figures].reverse()){const limb=f.limbs.findIndex(l=>Math.hypot(p.x-f.x-l[0],p.y-f.y-l[1])<19);if(limb>=0||Math.abs(p.x-f.x)<60&&p.y>f.y-75&&p.y<f.y+125){selected=f.id;gesture={f,limb,dx:p.x-f.x,dy:p.y-f.y};renderCast();render();return}}selected=null;renderCast();render()}else{if(recording)return toast('Background drawing pauses while recording.');gesture={start:p,stroke:{points:[p],color:ink,width:tool==='eraser'?brush*5:brush,erase:tool==='eraser'}};render()}});
canvas.addEventListener('pointermove',e=>{if(!gesture)return;const p=point(e);p.x=Math.max(0,Math.min(W,p.x));p.y=Math.max(0,Math.min(H,p.y));if(gesture.f){if(gesture.limb>=0){gesture.f.limbs[gesture.limb]=[Math.max(-125,Math.min(125,p.x-gesture.f.x)),Math.max(-120,Math.min(160,p.y-gesture.f.y))]}else{gesture.f.x=Math.max(70,Math.min(W-70,p.x-gesture.dx));gesture.f.y=Math.max(85,Math.min(H-125,p.y-gesture.dy))}}else if(tool==='line')gesture.stroke.points=[gesture.start,p];else gesture.stroke.points.push(p);render()});
function finishGesture(){if(gesture?.stroke){strokes.push(gesture.stroke);redo=[]}gesture=null;render()}
canvas.addEventListener('pointerup',finishGesture);canvas.addEventListener('pointercancel',finishGesture);
canvas.addEventListener('keydown',e=>{if(tool!=='select'||playing||exporting)return;const f=figures.find(a=>a.id===selected);const delta={ArrowLeft:[-5,0],ArrowRight:[5,0],ArrowUp:[0,-5],ArrowDown:[0,5]}[e.key];if(f&&delta){e.preventDefault();f.x=Math.max(70,Math.min(W-70,f.x+delta[0]));f.y=Math.max(85,Math.min(H-125,f.y+delta[1]));render()}});
function format(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+(t%60).toFixed(1).padStart(4,'0')}
function timeline(){const total=Math.max(10,duration,elapsed);$('ruler').replaceChildren(...Array.from({length:11},(_,i)=>{const s=document.createElement('span');s.textContent=(i*total/10).toFixed(total>10?0:0)+'s';return s}));$('currentTime').textContent=format(elapsed);$('duration').textContent=format(duration);$('scrub').max=String(Math.max(duration,.001));$('scrub').value=String(elapsed);$('playhead').style.left=Math.min(100,elapsed/total*100)+'%';$('recordingBar').style.display=duration>0?'block':'none';$('recordingBar').style.width=Math.max(1,duration/total*100-1)+'%'}
function snapshot(t){frames.push({t,figures:clone(figures)})}
function applyFrame(t){if(!frames.length)return;let low=0,high=frames.length-1;while(low<high){const mid=Math.ceil((low+high)/2);if(frames[mid].t<=t)low=mid;else high=mid-1}const a=frames[low],b=frames[Math.min(low+1,frames.length-1)],r=b.t===a.t?0:(t-a.t)/(b.t-a.t);figures=a.figures.map(f=>{const next=b.figures.find(n=>n.id===f.id)||f;return{...clone(f),x:f.x+(next.x-f.x)*r,y:f.y+(next.y-f.y)*r,limbs:f.limbs.map((p,i)=>p.map((v,j)=>v+(next.limbs[i][j]-v)*r))}})}
function state(){const busy=recording||exporting;$('record').classList.toggle('recording',recording);$('record').innerHTML='<span class="record-dot"></span>'+(recording?'Stop':'Record');$('record').disabled=exporting;$('play').disabled=!frames.length||busy;$('export').disabled=!frames.length||busy||playing;$('add').disabled=busy||playing;$('scrub').disabled=busy;$('rewind').disabled=busy;$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'Pause recording':'Play recording');$('status').textContent=exporting?'● Preparing your video':recording?'● Recording your story':playing?'● Your story is playing':'● Ready when you are';$('recordLabel').textContent=recording?'YOU’RE ON A ROLL':frames.length?'A LITTLE IDEA, BROUGHT TO LIFE':"LET'S MAKE A LITTLE MAGIC"}
function stopRecord(){if(!recording)return;elapsed=(performance.now()-startTime)/1000;duration=elapsed;snapshot(duration);recording=false;gesture=null;state();timeline();render();toast('Take captured. Press play to see your story.');}
$('record').onclick=()=>{if(recording)return stopRecord();if(!figures.length)return toast('Add a stick figure to start your story.');playing=false;gesture=null;setTool('select');frames=[];elapsed=duration=0;take++;$('take').textContent=String(take).padStart(2,'0');snapshot(0);recording=true;startTime=performance.now();state();render()};
$('play').onclick=()=>{if(playing){playing=false;state();return}if(elapsed>=duration)elapsed=0;playing=true;startTime=performance.now()-elapsed*1000;state();render()};$('rewind').onclick=()=>{playing=false;elapsed=0;applyFrame(0);state();timeline();render()};$('scrub').oninput=()=>{playing=false;elapsed=+$('scrub').value;applyFrame(elapsed);state();timeline();render()};$('loop').onclick=()=>{loop=!loop;$('loop').setAttribute('aria-pressed',loop)};
function tick(now){if(recording){elapsed=(now-startTime)/1000;duration=elapsed;if(!frames.length||elapsed-frames.at(-1).t>=1/30)snapshot(elapsed);timeline();if(elapsed>=120)stopRecord()}else if(playing){elapsed=(now-startTime)/1000;if(elapsed>=duration){if(loop&&!exporting){elapsed=0;startTime=now}else{elapsed=duration;playing=false;state()}}applyFrame(elapsed);timeline();render(exporting)}requestAnimationFrame(tick)}
$('export').onclick=async()=>{if(!canvas.captureStream||!window.MediaRecorder)return toast('Video export is unavailable in this browser. Try Chrome or Edge.');exporting=true;playing=false;elapsed=0;applyFrame(0);render(true);state();const stream=canvas.captureStream(30),chunks=[];let recorder;try{const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/mp4','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(chunks,{type:recorder.mimeType});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='my-stickfigure-story.'+(recorder.mimeType.includes('mp4')?'mp4':'webm');a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);exporting=false;playing=false;state();render();toast('Your story is ready. Video downloaded!')};recorder.start();playing=true;startTime=performance.now();toast('Creating your video… keep this tab open.');const end=()=>{if(!playing){if(recorder.state!=='inactive')recorder.stop()}else requestAnimationFrame(end)};requestAnimationFrame(end)}catch(error){stream.getTracks().forEach(t=>t.stop());exporting=false;playing=false;state();render();toast('This browser could not export video. Try Chrome or Edge.')}};
$('add').onclick=addFigure;document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{if(recording&&b.dataset.tool!=='select')return toast('Stop recording to edit your background.');setTool(b.dataset.tool)});
function palette(id,callback){$(id).querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{if(exporting||recording||playing)return toast('Stop the take before changing colors.');$(id).querySelectorAll('.swatch').forEach(s=>s.classList.remove('selected'));b.classList.add('selected');callback(b.dataset.color,b);render()})}palette('ink',(c,b)=>{ink=c;$('colorName').textContent=b.getAttribute('aria-label')});palette('paper',c=>paper=c);$('customColor').oninput=e=>{ink=e.target.value;$('colorName').textContent='Custom';$('ink').querySelectorAll('.swatch').forEach(s=>s.classList.remove('selected'))};$('brush').oninput=e=>{brush=+e.target.value;$('brushValue').textContent=brush+' px'};
function editBackground(fn){if(recording||playing||exporting)return toast('Stop the take to edit your background.');fn();render()}
$('undo').onclick=()=>editBackground(()=>{if(strokes.length)redo.push(strokes.pop())});$('redo').onclick=()=>editBackground(()=>{if(redo.length)strokes.push(redo.pop())});$('clear').onclick=()=>editBackground(()=>{if(strokes.length){redo.push(...strokes.splice(0).reverse());toast('Background cleared. Press Redo to restore your strokes.')}});
$('help').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=$('letsGo').onclick=()=>$('helpDialog').close();
figures.push(figure(710,305));selected=figures[0].id;renderCast();timeline();state();render();requestAnimationFrame(tick);

if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'add_stick_figure',description:'Add one stick figure to the scene and select it for puppeteering.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object.');if(recording||playing||exporting||figures.length>=8)throw new Error('Stop the take and ensure there is room in the cast.');addFigure();return{id:selected,count:figures.length}}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
